    code: ";; Welcome to Puffin! 🐧\n;; A tiny Racket-like teaching language, with gradual types.\n;; Press Run (or Cmd/Ctrl+Enter) to evaluate; try the REPL on the right.\n\n;; Programs are s-expressions, and grammars type them (docs/GRAMMARS.md).\n;; The quoted program below is checked against Arith when this compiles;\n;; the match is checked to cover every production.\n(define-grammar Arith\n  Int\n  (+ Arith Arith)\n  (* Arith Arith))\n(define (eval-arith [e : Arith]) : Int\n  (match e\n    [(? fixnum? n) n]\n    [`(+ ,a ,b) (+ (eval-arith a) (eval-arith b))]\n    [`(* ,a ,b) (* (eval-arith a) (eval-arith b))]))\n(println (eval-arith '(+ (* 3 4) (+ 1 2))))  ;; 15\n\n;; Hashes are immutable by default (persistent HAMTs natively);\n;; hash-set returns a NEW hash. make-hash/hash-set! exist when\n;; you really want mutation.\n(define ages (hash 'gwen 7 'finn 11))\n(define ages+ (hash-set ages 'puffin 1))\n(println (hash-ref ages+ 'finn))                   ;; 11\n(println (hash-has-key? ages 'puffin))             ;; #f (ages untouched)\n(println (equal? ages (hash-remove ages+ 'puffin))) ;; #t (value semantics)\n\n;; Named let, lists, guards:\n(define (evens-below [n : Int]) : (List Int)\n  (let loop ([i 0] [acc '()])\n    (cond [(< i n) (loop (+ i 1)\n                         (if (eq? (remainder i 2) 0) (cons i acc) acc))]\n          [else acc])))\n(println (evens-below 10))                         ;; (8 6 4 2 0)\n\n(match (list 'puffin 3)\n  [(list name k) #:when (< k 10) (list 'small name k)]\n  [_ 'big])\n",
