    code: ";; Gradual types (docs/TYPES.md, docs/GRAMMARS.md): grammars over\n;; s-expressions, define-types, annotations anywhere, _ everywhere else.\n;; Unannotated code runs unchanged.\n\n;; a define-type is a grammar plus constructors: (Some 1) is the list\n;; (Some 1), None the symbol None\n(define-type (Option a)\n  (None)\n  (Some a))\n\n;; a grammar describes the syntax itself -- no AST to convert to\n(define-grammar Expr\n  #:keywords (+ * neg)\n  Int\n  (+ Expr Expr)\n  (* Expr Expr)\n  (neg Expr))\n\n(define (eval-expr [e : Expr]) : Int\n  (match e\n    [(? fixnum? n) n]\n    [`(+ ,a ,b) (+ (eval-expr a) (eval-expr b))]\n    [`(* ,a ,b) (* (eval-expr a) (eval-expr b))]\n    [`(neg ,a) (- (eval-expr a))]))\n\n(println (eval-expr '(+ 1 (* 3 (neg 4)))))  ;; -11\n\n(: safe-div (-> Int Int (Option Int)))\n(define (safe-div a b)\n  (if (eq? b 0) None (Some (quotient a b))))\n\n(define (or-else [o : (Option Int)] [d : Int]) : Int\n  (match o\n    [(Some x) x]\n    [None d]))\n\n(println (or-else (safe-div 10 2) -1))   ;; 5\n(println (or-else (safe-div 10 0) -1))   ;; -1\n\n;; annotated let bindings + annotated lambda formals, mixed with plain\n(let ([xs : (List Int) (list 1 2 3)])\n  (println (foldl (lambda ([x : Int] acc) (+ x acc)) 0 xs)))  ;; 6\n\n(println (ann (+ 20 22) Int))  ;; 42\n\n;; higher-order over a define-type, mostly inferred\n(define (omap f o)\n  (match o\n    [(Some x) (Some (f x))]\n    [None None]))\n(println (or-else (omap (lambda (x) (* x x)) (Some 6)) 0))  ;; 36\n(or-else (omap (lambda (x) (* x x)) None) 99)               ;; 99\n",
