    code: ";; Persistent vs mutable is IN THE TYPES: allocators like make-hash\n;; return (Mut ...), and mutating prims demand it. Persistent values\n;; (hash ...), (set ...) stay on the plain types.\n\n(define h (make-hash))            ;; h : (Mut (Hash _ _))\n(hash-set! h 'a 1)                ;; fine: h is Mut\n(println (hash-ref h 'a))         ;; 1\n\n(define p (hash 'x 10))           ;; p : persistent -- hash-set returns a NEW hash\n(println (hash-ref (hash-set p 'y 20) 'y))   ;; 20\n(println (hash-has-key? p 'y))    ;; #f -- p itself is untouched\n\n;; ---- uncomment: mutating a persistent hash is a TYPE error ----\n\n;; (hash-set! (ann p (Hash Sym Int)) 'y 20)\n;;   error: typecheck: hash-set!: argument has type (Hash Sym Int), expected (Mut (Hash Sym Int)) [main.puf:15]\n\n;; variadic functions get real types: (->* (fixed ...) rest result)\n(: sum-all (->* (Int) Int Int))\n(define (sum-all base . rest)     ;; rest : (List Int) in the body\n  (let loop ([xs rest] [acc base])\n    (if (null? xs) acc (loop (cdr xs) (+ (car xs) acc)))))\n(println (sum-all 100 1 2 3))     ;; 106\n\n;; ---- uncomment: arity floor and rest types are enforced ----\n\n;; (sum-all)\n;;   error: typecheck: sum-all expects at least 1 arguments, got 0 [main.puf:27]\n\n;; (sum-all 1 \"two\")\n;;   error: typecheck: sum-all: argument has type Str, expected Int [main.puf:30]\n",
