    code: ";; higher-order + eta-expanded prims + equal?\n;; (: name t) declares the type of the define that follows --\n;; gradual style: annotate the boundaries, infer the rest\n(: map (-> (-> a b) (List a) (List b)))\n(define (map f xs) (if (null? xs) '() (cons (f (car xs)) (map f (cdr xs)))))\n(: filter (-> (-> a Bool) (List a) (List a)))\n(define (filter p xs)\n  (cond [(null? xs) '()]\n        [(p (car xs)) (cons (car xs) (filter p (cdr xs)))]\n        [else (filter p (cdr xs))]))\n(: foldl (-> (-> a b b) b (List a) b))\n(define (foldl f acc xs) (if (null? xs) acc (foldl f (f (car xs) acc) (cdr xs))))\n(println (map car (list (cons 1 2) (cons 3 4))))\n(println (filter (lambda ([n : Int]) (< n 4)) (list 1 5 2 8 3)))\n(println (foldl + 0 (list 1 2 3 4 5)))\n(println (equal? (list 1 (vector 2 3)) (list 1 (vector 2 3))))\n(println (equal? \"abc\" (string-append \"ab\" \"c\")))\n(println (eq? 'foo 'foo))\n",
